alter table public.exams add column purged_at timestamptz;
create function public.api_purge_exam(p_id uuid,p_actor uuid,p_title text) returns void language plpgsql set search_path='' as $$declare e public.exams;begin if not exists(select 1 from public.profiles where id=p_actor and role='admin' and active) then raise exception '无权限';end if;select * into e from public.exams where id=p_id for update;if e.id is null or e.status<>'deleted' or e.purged_at is not null then raise exception '试卷不在回收站';end if;if p_title<>e.title then raise exception '确认名称不匹配';end if;update public.exams set questions='[]',description='',tags='[]',review_reason=null,published_version_id=null,purged_at=now() where id=p_id;delete from public.exam_versions v where v.exam_id=p_id and not exists(select 1 from public.attempts a where a.exam_version_id=v.id);insert into public.audit_logs(actor_id,event,entity_id)values(p_actor,'exam_purged_preserving_history',p_id::text);end$$;
revoke all on function public.api_purge_exam(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.api_purge_exam(uuid,uuid,text) to service_role;
insert into public.system_config(key,value) values('registration_enabled','true') on conflict(key) do nothing;
